import sys
import heapq

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        n, x = map(int, sys.stdin.readline().split())
        stations = list(map(int, sys.stdin.readline().split()))
        gas, steps, used = 0, 0, [0] * (x + 1)
        for s in stations:
            heapq.heappush(used, (s, gas))
            for i in range(s, x + 1):
                used[i] = max(used[i], gas + 1)
            gas = used[-1][0]
        left, right, ans = 0, max(stations) + 1, float('inf')
        while left <= right:
            mid = (left + right + 1) // 2
            gas, steps = mid, 0
            for i, s in enumerate(stations):
                if i + 1 != len(stations) and stations[i + 1] > s + mid:
                    gas -= s
                    steps += 1
                    if gas <= 0:
                        break
                if gas - mid < 0:
                    break
            if steps >= n:
                right = mid - 1
                ans = min(ans, mid)
            else:
                left = mid
        print(ans if ans != float('inf') else -1)

solve()
```

