import itertools, heapq

def solve():
    def manhattan_distance(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def possible_pairs( seq ):
        for i in range( len( seq ) - 1 ):
            for j in range( i + 1, len( seq ) ):
                yield ( seq[i], seq[j] )

    def min_dist_between_points( points ):
        dist_pairs = [ ( p1, p2, manhattan_distance( p1, p2 ) ) for p1, p2 in itertools.combinations( points, 2 ) ]
        dist_pairs = sorted( dist_pairs )
        heapq.heapify( dist_pairs )
        return sum( heapq.heappop( dist_pairs )[2] for _ in range( len( points ) - 1 ) )

    t = int( input() )
    for _ in range( t ):
        n = int( input() )
        points = list( map( int, input().split() ) )
        points = sorted( points )
        pairs = list( possible_pairs( points ) )
        pairs.sort( key=lambda x: min_dist_between_points( points[x] ) )
        path = []
        path.append( pairs.pop( 0 ) )
        for _ in range( n - 1 ):
            path.append( pairs.pop( pairs.index( min( pairs, key=lambda x: manhattan_distance( path[-1], x ) ) ) ) )
        print( min_dist_between_points( points ) )
        for p in path:
            print(*p)
        print()

solve()
