def solve(arr):
    n = len(arr)
    bit = [0] * (n + 1)  # Binary Indexed Tree

    def update(x, v):
        while x < n:
            bit[x] ^= v
            x += (x & -x)  # bitwise right-most set bit

    def sum_range(x):
        res = 0
        while x:
            res ^= bit[x]
            x -= (x & -x)
