import math

def PrimeSieve(n):
    primes = [True for i in range(n + 1)]
    primes[0] = primes[1] = False
    for i in range(2, int(math.sqrt(n)) + 1):
        if primes[i]:
            for j in range(i**2, n + 1, i):
                primes[j] = False
    return primes

primes = PrimeSieve(10000)
def solve(a):
    n = len(a)
    if all(prime in primes and a.count(prime) > 1 for prime in a):
        return -1
    l_b, l_c = n // 2, n // 2
    b, c = [0] * l_b, [0] * l_c
    def backtrack(i, b_len, c_len):
        if i == n:
            if b_len > 0 and c_len > 0 and all(c[j] not in b and b[j] not in c for j in range(b_len)):
                return True
        for j in range(1, n+1):
            if primes[j] and a.count(j) > 0:
                a[a.index(j)] = 0 # mark as used
                if i < b_len:
                    b[i] = j
                    if backtrack(i + 1, b_len, c_len):
