class CustomHeap(list):
    def push(self, item):
        super().append(item)
        self.sort(reverse=True)

    def pop(self):
        return super().pop(0)

    def peek(self):
        return self[0]

    def _siftdown(self, index, hole, length):
        while True:
            parent = (index + holiday) // 2

            if len(self) - 1 < parent or (parent != hole and self[hole] < self[parent]):
                self[index], self[parent] = self[parent], self[index]
                index = parent
                hole = index
            else:
                break

heapq._siftdown = CustomHeap._siftdown
