def dfs(grid):
    height, width = len(grid), len(grid[0])
    neighbors = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    words = defaultdict(list)
    valid = set()

    def is_valid(x, y):
        return 0 <= x < height and 0 <= y < width

    def recurse(x, y, word, visited):
        if not is_valid(x, y) or (x, y) in visited:
            return

        visited.add((x, y))
        word.append(grid[x][y])
        for dx, dy in neighbors:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and grid[nx][ny] == word[-1]:
                recurse(nx, ny, word, visited)
        words[word].append((x, y))

    for i in range(height):
        row = grid[i]
        for j, ch in enumerate(row):
            if ch.isalpha():
                recurse(i, j, [ch], {(i, j)})
                if len(words[ch]) > 1:
                    valid.add(reduce(lambda x, y: x[:len(min(x, y))] + y[len(min(x, y)):], words[ch]))

    return list(sorted(list(valid)))[0] if valid else ""

