def solve(n, a, m, b, mn, Tsondu_moves):
    @lru_cache(maxsize=None)
    def dp(s, t, Tsondu_alive=1, Tenzing_alive=1):
        if s == 0 and t == 0:
            return Tsondu_alive > Tenzing_alive
        if s < 0 or t < 0:
            return Tenzing_alive > Tsondu_alive
        if (s, t, Tsondu_alive, Tenzing_alive) in mn:
