import heapq
from collections import defaultdict

class TrieNode:
    def __init__(self):
        self.children = defaultdict(TrieNode)
        self.end_of_word = False
        self.freq = float('inf')

def buildMinHeap(nodes):
    return [(- Node.freq, Node) for Node in nodes]

def dijkstra(trie):
    q = buildMinHeap(list(trie.values()))
    while q:
        f, node = heapq.heappop(q)
        if not node.end_of_word:
            for child in node.children.values():
                heapq.heappush(q, (- child.freq, child))
                child.freq = min(child.freq, f + 1)
    return min(node.freq for node in trie.values() if node.end_of_word)

