    C = [[] for _ in range(n)]
    freq = [0] * 256
    for i, c in enumerate(s):
        freq[ord(c)] += 1
        C[freq[ord(c)]].append(i)

    heap = [(-freq[c], i, 0) for i, c in enumerate(s)]
    heapq.heapify(heap)

    sa = [0] * n
    for _ in range(n):
        _, k, i = heapq.heappop(heap)
        sa[i] = k
        for j in C[k + 1]:
            heapq.heappush(heap, (freq[s[j]] - 1, j, i + 1))
            freq[s[j]] -= 1

    lcp = [0] * n
    for i in range(1, n):
        if sa[i] != sa[i - 1]:
            k = 1
        else:
            k = lcp[i - 1] + 1

        while s[sa[i] + k] == s[sa[i - 1] - k]:
            k += 1

        lcp[i] = k

    return sa, lcp

