MOD = int(1e9 + 7)

def solve():
    n = int(sys.stdin.readline())
    if n == 1:
        return [1]

    def d(k, last):
        if k == 1:
            return 1
        cnt = [0] * n
        for i in range(1, last + 1):
            cnt[i - i // 2 - 1] += 1
        res = 0
        for i in range(1, n):
            res = (res + cnt[i] * (n - i)) % MOD
            cnt[i] += cnt[i - 1]
        return (res * d(k - 1, n)) % MOD

    @functools.lru_cache(maxsize=None)
    def dp(cur, last, cnt):
        if cur == n:
            return 1
        res = 0
        for i in range(1, last + 1):
            if cnt[i - i // 2 - 1] > 0:
                cnt[i - i // 2 - 1] -= 1
                res = (res + dp(cur + 1, min(i, last), cnt)) % MOD
                cnt[i - i // 2 - 1] += 1
        return res

    last = n
    cnt = [0] * n
    res = 0
    for i in range(1, n):
        cnt[i - i // 2 - 1] += 1
        res = (res + d(n - i - 1, i)) % MOD
    for i in range(1, n):
