import collections
import sys

def qsort(q):
    if len(q) < 3:
        return q
    pivot = q.popleft()
    left = collections.deque()
    mid = collections.deque([pivot])
    right = collections.deque()

    while left or mid or right:
        item = left.popleft() if left else mid.popleft()
        if item < pivot:
            left.append(item)
        elif item > pivot:
            right.append(item)
        else:
            mid.append(item)

    return qsort(left) + mid + qsort(right)

