import collections
import itertools

def group_adjacent(board, r, c):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    group = [(r, c)]
    for dr, dc in directions:
        rr, cc = r + dr, c + dc
        if 0 <= rr < len(board) and 0 <= cc < len(board):
            if board[rr][cc] in group:
                group.append((rr, cc))
                board[rr][cc] = len(group)

    return group, board

def is_valid(board):
    groups = collections.defaultdict(list)
    for r, row in enumerate(board):
        for c, _ in enumerate(row):
            group, _ = group_adjacent(board, r, c)
            if len(group) > 1:
                for a, b in itertools.combinations(group, 2):
                    if abs(a[0] - b[0]) == abs(a[1] - b[1]):
                        return False
            groups[len(group)].append((r, c))
