                    heappush(unvisited, (distance + abs(box[0]), (box[0] + 1, box[1])))
                else:
                    heappush(unvisited, (distance + abs(box[0] + box[0]), (box[0] - 1, box[1])))
                    heappush(unvisited, (distance + abs(box[0]), (box[0] + 1, box[1])))
            if box[1] != 0:
                if box[1] > 0:
                    heappush(unvisited, (distance + abs(box[1] - box[1] - 1), (box[0], box[1] - 1)))
