from functools import lru_cache

def BIT_MANIPulation(n, m):
    bit = [0]*((n+m)*2 + 1)

    @lru_cache((n+m)*2 + 1)
    def dp(mask):
        if mask == 0:
            return 0
        res = float('inf')
        for j in range(1, (n+m)*2 + 1):
            if (mask & j) == j: # a box 'exists' at (i,j-n)
                for k in [j-1, j+1]:
                    if (mask & k) == k:  # If there exists another box at the new position
                        res = min(res, 1 + dp(bit[(j+k)//2]^k))
        return res

    for i in range(n+1):
        if i % 2 == 0:
            bit[i] = 1 << (i//2)
        for j in range(m+1):
            bit[n+j] |= 1 << ((i+j)//2)

    res = dp((1 << n) - 1)
    return res if res != float('inf') else -1

