        if p < 3 or p > n or p*(n-1) >= n*3 or p*(n-1) % (n-1) != n-1:
            continue
        candidates.append((p, n-1//p))
    candidates.sort()

    ans = [-1]*n
    for p, exp in candidates:
        for i in range(n):
            if not ans[i]:
                ans[i] = p
                break
            if i+1 != ans[i]*(1-exp)//p:
