    graph = [[-1] * n for _ in range(n)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if primes[j]:
                graph[i - 1][j - 1] = 0
            else:
                graph[i - 1][j - 1] = 1
    floyd(graph)
    dist = [[0] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 1 if primes[i + 1] else 0
