        for n, w in graph[v]:
            t = d + w
            if t < dist[chr(ord(n)+ord('A')-ord(v))]:
                dist[chr(ord(n)+ord('A')-ord(v))] = t
                result[ord(n)-ord('A')] = chr(ord('A')+ord(v)-ord('B'))
                heapq.heappush(q, (t, chr(ord(n)+ord('A')-ord(v))))

    return ''.join(result)
