import sys
from itertools import permutations

def get_permutations(s):
    return [''.join(p) for p in permutations(s)]

def same_sequences(a, b):
    if len(a) != len(b):
        return False

    for i in range(len(a)):
        if a[i] != b[i]:
            return False

    return True

def next_state(a):
    if len(a) < 2:
        return a

    min_max = max(min(a[0], a[1]), max(a[0], a[1]))
    if min_max == min(a[0], a[1]):
        return ''.join(sorted(a[1:]))
    else:
        return ''.join(reversed(a[1:]))

def can_make_equal(a, b):
    sequences = get_permutations(a)
    for sequence in sequences:
        if same_sequences(sequence, b):
            return True

    states = set([a])
    while True:
        for sequence in sequences:
            new_state = ''.join(map(next_state, sequence))
            if new_state in states:
                continue
            states.add(new_state)
            if same_sequences(new_state, b):
