import numpy as np

def solution(n, d, permutation=None, memo={}):
    if n < 2:
        return 0, permutation
    if n in memo:
        return memo[n]
    cost = 0
    if permutation is None:
        permutation = np.array([-1] * n)

    for i in range(1, n):
        permutation[i] = i
        if i >= 2 and permutation[i] * d == permutation[i - 1]:
            cost += 1
        cost_i, next_permutation = solution(n - 1, permutation[i] * d, permutation[:i] + permutation[i+1:], memo)
        cost += cost_i
        if cost > memo.get(n, 0):
            memo[n] = (cost, permutation.tolist())
        if cost == memo[n]:
            break
        permutation[i] = -1
    else:
        memo[n] = (cost, permutation.tolist())

    return memo[n]

def solve():
