import functools

def bitwise_xor(matrix1, matrix2):
    return [list(map(functools.reduce, zip(zip(*matrix1), zip(*matrix2)), operator.xor))]

def floyd_warshall(matrix):
    n = len(matrix)
    shortest_paths = [[float("inf")] * n for _ in range(n)]
    for k in range(n):
        for i in range(n):
            for j in range(n):
                shortest_paths[i][j] = min(shortest_paths[i][j], shortest_paths[i][k] + shortest_paths[k][j])
    return shortest_paths

def solve():
